-- 101_vettori_cap_riaddebito_simulazioni.sql
--
-- Tre cose che servono alla Simulazione per diventare il punto di partenza del
-- lavoro di backoffice, invece di un calcolatore a lato:
--
--   1) CAP -> PROVINCIA. Chi spedisce ha davanti un indirizzo, non una sigla.
--   2) RIADDEBITO CONFIGURABILE. La tabella esiste dalla 087 ed e' popolata
--      dalla 088, ma nessuna riga di codice la usa e nessuno puo' modificarla.
--   3) LA SIMULAZIONE E' UNA DECISIONE, e va conservata.
--
-- ============================================================================
-- PERCHE' UNA TABELLA DI CAP E NON UN CALCOLO SUL PREFISSO
-- ============================================================================
-- Il prefisso da solo non basta: 12071 sta a cavallo fra Cuneo e Savona, 18025
-- fra Cuneo e Imperia, e Cuneo e' dentro l'area Trading Post mentre Savona e
-- Imperia non lo sono. Su quei due CAP il prefisso sceglierebbe il vettore
-- sbagliato.
--
-- La tabella viene da ISTAT + ANCI (dataset comuni-json, 7.904 comuni) ed e'
-- stata verificata contro i CAP che compaiono davvero nelle nostre bolle:
-- 210 coppie CAP/provincia estratte da bi.trasporti_documenti, di cui
--   198 riprodotte esattamente,
--     0 in contraddizione,
--    12 assenti — 4 esteri o San Marino, 8 CAP italiani di frazioni.
-- Sugli 8 italiani il ripiego per prefisso a 3 cifre ne indovina 7; il solo
-- errore (23080, Lecco letto come Sondrio) non cambia zona tariffaria per
-- nessun vettore.
--
-- Il ripiego per prefisso e' quindi ammesso, ma solo dopo la ricerca esatta e
-- dichiarandolo all'operatore. Sui 205 prefissi a 3 cifre esistenti, 194
-- puntano a una sola provincia; degli 11 restanti soltanto 120 e 180
-- attraversano il confine di una zona tariffaria reale.

-- ============================================================
-- 1) CAP
-- ============================================================
CREATE TABLE IF NOT EXISTS vettori.cap_province (
  cap        char(5) PRIMARY KEY CHECK (cap ~ '^[0-9]{5}$'),
  -- Piu' di una provincia = il CAP sta a cavallo: l'interfaccia deve chiedere,
  -- non scegliere. Sono due in tutta Italia, ma sono due errori di vettore.
  province   char(2)[] NOT NULL,
  comuni     text[] NOT NULL,
  -- Enclave con CAP di forma italiana: San Marino e Citta del Vaticano. Senza
  -- questa distinzione 47896 verrebbe risolto per prefisso come Rimini, e una
  -- spedizione internazionale uscirebbe con una tariffa nazionale.
  estero     boolean NOT NULL DEFAULT false,
  fonte      text NOT NULL DEFAULT 'anci_istat'
               CHECK (fonte IN ('anci_istat', 'gestionale', 'manuale')),
  aggiornato_il timestamptz NOT NULL DEFAULT now(),
  CHECK (estero OR cardinality(province) >= 1)
);

COMMENT ON TABLE vettori.cap_province IS
  'CAP italiani con la provincia. Fonte ISTAT + ANCI, verificata contro i 210 CAP reali delle nostre bolle senza contraddizioni. fonte = manuale per i CAP aggiunti da un operatore quando la ricerca fallisce.';
COMMENT ON COLUMN vettori.cap_province.province IS
  'Piu di un elemento significa CAP a cavallo di due province: 12071 (CN/SV) e 18025 (CN/IM). Chi risolve deve chiedere, invece di prendere la prima.';

CREATE TABLE IF NOT EXISTS vettori.cap_prefissi (
  prefisso   char(3) PRIMARY KEY CHECK (prefisso ~ '^[0-9]{3}$'),
  province   char(2)[] NOT NULL CHECK (cardinality(province) >= 1)
);

COMMENT ON TABLE vettori.cap_prefissi IS
  'Ripiego per i CAP assenti dall''elenco esatto: le province che condividono le prime tre cifre. Chi lo usa deve dichiararlo, perche e una deduzione e non un dato.';

TRUNCATE vettori.cap_province;
