-- Gli enclave con il CAP che sembra italiano. Senza questa riga, 47896
-- (Faetano) cadrebbe nel ripiego per prefisso e verrebbe tariffato come
-- Rimini: sono tre bolle sulle nostre, ed e una quotazione internazionale
-- presentata come nazionale.
INSERT INTO vettori.cap_province (cap, province, comuni, fonte, estero)
SELECT lpad(n::text, 5, '0'), ARRAY[]::char(2)[], ARRAY['Repubblica di San Marino'], 'manuale', true
  FROM generate_series(47890, 47899) AS n
ON CONFLICT (cap) DO NOTHING;

-- La Citta del Vaticano NON e in questo elenco, e non e una dimenticanza:
-- 00120 sta gia nella lista ANCI come Roma, e i vettori la consegnano come
-- Roma. San Marino invece e davvero una destinazione internazionale, con
-- quotazione a parte. Trattarle allo stesso modo sarebbe simmetrico e sbagliato.

-- I CAP che il gestionale conosce e l'elenco ANCI no diventano righe di fonte
-- `gestionale`: sono destinazioni nostre, viste sul campo, e valgono piu di una
-- deduzione per prefisso. Cassina de Pecchi e Pessano con Bornago arrivano da
-- qui.
--
-- Il filtro sulle sigle davvero esistenti non e pignoleria: sulle nostre bolle
-- compaiono provincia `D` (Aldingen, Germania), `ZB` (Breukelen, Paesi Bassi) e
-- `RSM`, che entrerebbero in una tabella usata per scegliere un vettore.
-- Resta dentro 80841 Carate Brianza, che e un refuso del gestionale per 20841
-- ripetuto su 18 bolle: la provincia pero e giusta, e chi ricopia quel CAP
-- dall anagrafica trova comunque la risposta corretta.
INSERT INTO vettori.cap_province (cap, province, comuni, fonte)
SELECT d.soggetto_cap,
       ARRAY[upper(max(d.soggetto_provincia))]::char(2)[],
       ARRAY[coalesce(max(d.soggetto_localita), 'da confermare')],
       'gestionale'
  FROM bi.trasporti_documenti d
 WHERE d.soggetto_cap ~ '^[0-9]{5}$'
   AND upper(d.soggetto_provincia) IN (
         SELECT DISTINCT unnest(c.province) FROM vettori.cap_province c
       )
 GROUP BY d.soggetto_cap
HAVING count(DISTINCT upper(d.soggetto_provincia)) = 1
ON CONFLICT (cap) DO NOTHING;

/**
 * Risoluzione di un CAP.
 *
 * `certo` distingue il dato dalla deduzione, ed e la ragione per cui questa
 * funzione non restituisce una provincia secca: chiamarla e ottenere SO per un
 * CAP di Lecco senza saperlo e il modo migliore per scoprire l errore in
 * fattura, tre mesi dopo.
 */
CREATE OR REPLACE FUNCTION vettori.risolvi_cap(p_cap text)
RETURNS TABLE (province char(2)[], comuni text[], fonte text, certo boolean, estero boolean)
LANGUAGE sql
STABLE
AS $fn$
  WITH normalizzato AS (
    SELECT lpad(btrim(coalesce(p_cap, '')), 5, '0') AS cap
  )
  SELECT c.province, c.comuni, c.fonte, cardinality(c.province) = 1 AND NOT c.estero, c.estero
    FROM vettori.cap_province c, normalizzato n
   WHERE c.cap = n.cap
  UNION ALL
  -- Il ripiego per prefisso scatta solo se il CAP non e in elenco: un CAP noto
  -- come estero non deve mai finire qui dentro e diventare una provincia.
  SELECT p.province, ARRAY[]::text[], 'prefisso', false, false
    FROM vettori.cap_prefissi p, normalizzato n
   WHERE p.prefisso = left(n.cap, 3)
     AND NOT EXISTS (
       SELECT 1 FROM vettori.cap_province c2 WHERE c2.cap = n.cap
     )
  LIMIT 1;
$fn$;

-- ============================================================
-- 2) RIADDEBITO CONFIGURABILE
-- ============================================================
-- La tabella c'era gia dalla 087 e conteneva i valori 2026 dalla 088; mancava
-- chi potesse cambiarli e la traccia di chi lo ha fatto.
ALTER TABLE vettori.riaddebito_scaglioni
  ADD COLUMN IF NOT EXISTS base_peso text NOT NULL DEFAULT 'tassabile'
    CHECK (base_peso IN ('reale', 'tassabile')),
  ADD COLUMN IF NOT EXISTS creato_da uuid REFERENCES public.utenti(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS creato_il timestamptz NOT NULL DEFAULT now();

COMMENT ON COLUMN vettori.riaddebito_scaglioni.base_peso IS
  'Su quale peso si legge lo scaglione. tassabile = lo stesso peso su cui fattura il vettore, cioe il maggiore fra reale e volumetrico: rende confrontabili costo e ricavo. reale = solo la bilancia. Vale per tutta la versione, e la RPC rifiuta versioni con valori diversi. Da confermare con chi emette gli addebiti.';

/**
 * Salva una versione intera della tabella di riaddebito.
 *
 * Versione, non riga: cambiare un solo importo lasciando agli altri la vecchia
 * data di validita produrrebbe una tabella che non e mai esistita. La versione
 * aperta viene chiusa il giorno prima, cosi i mesi gia controllati continuano a
 * leggere gli importi di allora.
 */
CREATE OR REPLACE FUNCTION vettori.salva_riaddebito_scaglioni(
  p_valido_dal date,
  p_base_peso text,
  p_scaglioni jsonb,
  p_utente_id uuid
)
RETURNS integer
LANGUAGE plpgsql
AS $fn$
DECLARE
  v_righe   jsonb[];
  v_riga    jsonb;
  v_atteso  numeric := 0;
  v_n       integer := 0;
BEGIN
  IF p_base_peso NOT IN ('reale', 'tassabile') THEN
    RAISE EXCEPTION 'Base peso non ammessa: %', p_base_peso USING ERRCODE = 'check_violation';
  END IF;
  IF jsonb_typeof(p_scaglioni) <> 'array' OR jsonb_array_length(p_scaglioni) = 0 THEN
    RAISE EXCEPTION 'Serve almeno uno scaglione' USING ERRCODE = 'check_violation';
  END IF;

  SELECT array_agg(s ORDER BY (s->>'peso_da')::numeric)
    INTO v_righe
    FROM jsonb_array_elements(p_scaglioni) AS s;

  -- Stessa regola dei listini: dallo zero, consecutivi, senza buchi ne
  -- sovrapposizioni. Un buco non e un dettaglio formale: e una spedizione che
  -- non verrebbe addebitata a nessuno.
  FOREACH v_riga IN ARRAY v_righe LOOP
    IF v_atteso IS NULL THEN
      RAISE EXCEPTION 'Lo scaglione aperto deve essere l ultimo'
        USING ERRCODE = 'check_violation';
    END IF;
    IF (v_riga->>'peso_da')::numeric IS DISTINCT FROM v_atteso THEN
      RAISE EXCEPTION 'Gli scaglioni devono partire da zero ed essere consecutivi: atteso peso_da %, trovato %',
        v_atteso, v_riga->>'peso_da' USING ERRCODE = 'check_violation';
    END IF;
    IF nullif(v_riga->>'peso_a', '') IS NULL THEN
      v_atteso := NULL;
    ELSE
      IF (v_riga->>'peso_a')::numeric <= (v_riga->>'peso_da')::numeric THEN
        RAISE EXCEPTION 'La soglia finale deve superare quella iniziale'
          USING ERRCODE = 'check_violation';
      END IF;
      v_atteso := (v_riga->>'peso_a')::numeric;
    END IF;
    v_n := v_n + 1;
  END LOOP;

  IF v_atteso IS NOT NULL THEN
    RAISE EXCEPTION 'Manca lo scaglione finale aperto: senza, le spedizioni oltre % kg non avrebbero addebito', v_atteso
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE vettori.riaddebito_scaglioni
     SET valido_al = p_valido_dal - 1
   WHERE valido_al IS NULL
     AND valido_dal < p_valido_dal;

  DELETE FROM vettori.riaddebito_scaglioni WHERE valido_dal = p_valido_dal;

  INSERT INTO vettori.riaddebito_scaglioni
    (valido_dal, peso_da, peso_a, importo, nota, base_peso, creato_da)
  SELECT p_valido_dal,
         (s->>'peso_da')::numeric,
         nullif(s->>'peso_a', '')::numeric,
         nullif(s->>'importo', '')::numeric,
         nullif(s->>'nota', ''),
         p_base_peso,
         p_utente_id
    FROM unnest(v_righe) AS s;

  RETURN v_n;
END;
$fn$;

ALTER TABLE vettori.riaddebito_clienti
  ADD COLUMN IF NOT EXISTS creato_da uuid REFERENCES public.utenti(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS creato_il timestamptz NOT NULL DEFAULT now();

-- ============================================================
-- 3) LA SIMULAZIONE E UNA DECISIONE, E VA CONSERVATA
-- ============================================================
-- Serve a rispondere fra sei mesi alla domanda: perche quel giorno abbiamo
-- scelto TNT? I listini cambiano, quindi rifare il calcolo oggi darebbe un
-- altro risultato e non sarebbe una risposta.
CREATE TABLE IF NOT EXISTS vettori.simulazioni (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  eseguita_da      uuid REFERENCES public.utenti(id) ON DELETE SET NULL,
  eseguita_il      timestamptz NOT NULL DEFAULT now(),
  data_riferimento date NOT NULL,
  direzione        text NOT NULL DEFAULT 'uscita'
                     CHECK (direzione IN ('entrata', 'uscita')),
  cap              text,
  provincia        char(2),
  fonte_provincia  text CHECK (fonte_provincia IN ('cap', 'prefisso', 'manuale')),
  colli            integer NOT NULL CHECK (colli > 0),
  peso_kg          numeric(14,3) NOT NULL CHECK (peso_kg > 0),
  condizioni       text[] NOT NULL DEFAULT '{}',
  -- I gruppi di colli come li ha inseriti chi spedisce, prima di diventare misure.
  gruppi           jsonb NOT NULL DEFAULT '[]'::jsonb
                     CHECK (jsonb_typeof(gruppi) = 'array'),
  -- Tutti i vettori confrontati, non solo il vincitore: e la prova che
  -- l alternativa era stata guardata.
  esiti            jsonb NOT NULL DEFAULT '[]'::jsonb
                     CHECK (jsonb_typeof(esiti) = 'array'),
  vettore_scelto_id uuid REFERENCES vettori.vettori(id) ON DELETE SET NULL,
  costo_previsto      numeric(14,4),
  riaddebito_previsto numeric(14,4),
  spedizione_id    uuid REFERENCES vettori.spedizioni(id) ON DELETE SET NULL,
  note             text
);

CREATE INDEX IF NOT EXISTS idx_simulazioni_data
  ON vettori.simulazioni (eseguita_il DESC);
CREATE INDEX IF NOT EXISTS idx_simulazioni_spedizione
  ON vettori.simulazioni (spedizione_id) WHERE spedizione_id IS NOT NULL;

COMMENT ON TABLE vettori.simulazioni IS
  'Ogni confronto fra vettori confermato dal backoffice, con tutti gli esiti e non solo quello scelto. La riga sopravvive alla spedizione: il riferimento e ON DELETE SET NULL.';

-- La bolla nata da una simulazione si riconosce, e puo non avere ancora il
-- numero: chi decide il vettore non sempre ha gia registrato la bolla su
-- Impresa. `da_numerare` e la coda di chi deve tornarci sopra.
ALTER TABLE vettori.spedizioni DROP CONSTRAINT IF EXISTS spedizioni_origine_check;
ALTER TABLE vettori.spedizioni
  ADD CONSTRAINT spedizioni_origine_check
  CHECK (origine IN ('gestionale', 'manuale', 'excel_storico', 'simulazione'));

ALTER TABLE vettori.spedizioni DROP CONSTRAINT IF EXISTS spedizioni_stato_check;
ALTER TABLE vettori.spedizioni
  ADD CONSTRAINT spedizioni_stato_check
  CHECK (stato IN ('attesa', 'abbinata', 'senza_fattura', 'ignorata', 'da_numerare'));

COMMENT ON COLUMN vettori.spedizioni.stato IS
  'da_numerare = nata da una simulazione confermata senza numero di bolla. Finche resta cosi non puo agganciarsi al gestionale, perche il numero e la chiave: per questo deve stare in una coda visibile invece di sparire in fondo all elenco.';

/**
 * Creazione della bolla manuale, estesa alla simulazione.
 *
 * Il numero diventa facoltativo e si aggiungono destinazione e origine. Le
 * chiavi nuove sono tutte opzionali, quindi le chiamate della pagina Bolle
 * continuano a comportarsi esattamente come prima.
 */
CREATE OR REPLACE FUNCTION vettori.crea_bolla_manuale(p_payload jsonb)
RETURNS uuid
LANGUAGE plpgsql
AS $fn$
DECLARE
  v_spedizione_id uuid;
  v_misura jsonb;
  v_numero text := nullif(btrim(coalesce(p_payload->>'numero_riferimento', '')), '');
  v_norm   text := nullif(btrim(coalesce(p_payload->>'numero_riferimento_norm', '')), '');
BEGIN
  IF (v_numero IS NULL) <> (v_norm IS NULL) THEN
    RAISE EXCEPTION 'Numero di bolla e forma normalizzata devono esserci o mancare insieme'
      USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO vettori.spedizioni (
    direzione, vettore_id, numero_riferimento, numero_riferimento_norm,
    data_documento, controparte_codice, controparte_nome,
    zona_cap, zona_provincia, fonte_zona,
    colli_bolla, peso_bolla, origine, stato, aggiornata_il
  ) VALUES (
    p_payload->>'direzione',
    nullif(p_payload->>'vettore_id', '')::uuid,
    v_numero,
    v_norm,
    (p_payload->>'data_documento')::date,
    nullif(p_payload->>'controparte_codice', ''),
    p_payload->>'controparte_nome',
    nullif(p_payload->>'zona_cap', ''),
    nullif(p_payload->>'zona_provincia', '')::char(2),
    nullif(p_payload->>'fonte_zona', ''),
    (p_payload->>'colli_bolla')::int,
    (p_payload->>'peso_bolla')::numeric,
    coalesce(nullif(p_payload->>'origine', ''), 'manuale'),
    CASE WHEN v_numero IS NULL THEN 'da_numerare' ELSE 'attesa' END,
    now()
  )
  RETURNING id INTO v_spedizione_id;

  FOR v_misura IN
    SELECT * FROM jsonb_array_elements(coalesce(p_payload->'misure', '[]'::jsonb))
  LOOP
    INSERT INTO vettori.bolla_misure (
      spedizione_id, quantita, lunghezza_cm, larghezza_cm, altezza_cm,
      peso_reale_kg, volume_m3, fonte, inserito_da, modificato_da
    ) VALUES (
      v_spedizione_id,
      (v_misura->>'quantita')::int,
      (v_misura->>'lunghezza_cm')::numeric,
      (v_misura->>'larghezza_cm')::numeric,
      (v_misura->>'altezza_cm')::numeric,
      (v_misura->>'peso_reale_kg')::numeric,
      (v_misura->>'volume_m3')::numeric,
      coalesce(nullif(p_payload->>'fonte_misure', ''), 'manuale'),
      nullif(p_payload->>'utente_id', '')::uuid,
      nullif(p_payload->>'utente_id', '')::uuid
    );
  END LOOP;

  RETURN v_spedizione_id;
END;
$fn$;

-- ============================================================
-- 4) SICUREZZA
-- ============================================================
ALTER TABLE vettori.cap_province  ENABLE ROW LEVEL SECURITY;
ALTER TABLE vettori.cap_prefissi  ENABLE ROW LEVEL SECURITY;
ALTER TABLE vettori.simulazioni   ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON FUNCTION vettori.risolvi_cap(text) FROM public, anon, authenticated;
REVOKE ALL ON FUNCTION vettori.salva_riaddebito_scaglioni(date, text, jsonb, uuid) FROM public, anon, authenticated;
REVOKE ALL ON FUNCTION vettori.crea_bolla_manuale(jsonb) FROM public, anon, authenticated;

GRANT USAGE ON SCHEMA vettori TO service_role;
GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA vettori TO service_role;
GRANT EXECUTE ON FUNCTION vettori.risolvi_cap(text) TO service_role;
GRANT EXECUTE ON FUNCTION vettori.salva_riaddebito_scaglioni(date, text, jsonb, uuid) TO service_role;
GRANT EXECUTE ON FUNCTION vettori.crea_bolla_manuale(jsonb) TO service_role;

NOTIFY pgrst, 'reload schema';
